SELECT daily_closing_status_id
FROM daily_closing
WHERE business_date = #{businessDate}

mapper.update:


UPDATE daily_closing
SET daily_closing_status_id = #{inProgress},
    started_at              = #{startedAt},
    finished_at             = NULL
WHERE business_date = #{businessDate}
  AND daily_closing_status_id = #{failed}


UPDATE daily_closing
SET daily_closing_status_id = #{status},
    finished_at             = #{finishedAt}
WHERE business_date = #{businessDate}
  AND daily_closing_status_id = #{inProgress}
